using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>()
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// 2) Probe without throwing: TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"TryGetTypeInfo succeeded for Person → {info!.Type.Name}");
}

// Now demonstrate "not available" — use an options instance with NO resolver
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
{
    Console.WriteLine($"Unexpectedly found metadata: {missing!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo returned false for Person (no metadata available) — no exception thrown.");
}

record Person(string Name, int Age);

// A resolver that never resolves anything
class EmptyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

